'use strict';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',car:'M5 17H3v-6l2-6h14l2 6v6h-2 M5 17h14 M5 17v3 M19 17v3 M3 11h18 M6 14h2 M16 14h2',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16 M8 14h3 M8 17h6',route:'M5 4a2 2 0 1 0 0 .1 M5 6v7a4 4 0 0 0 4 4h6 M15 17l-3-3 M15 17l-3 3 M19 4v8 M16 7l3-3 3 3',wallet:'M3 5h17v15H3z M3 8h17 M15 12h7v5h-7z M17 14h1',network:'M9 3h6v5H9z M2 16h6v5H2z M16 16h6v5h-6z M12 8v4 M5 16v-4h14v4',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3z M12 5v17',layers:'m12 2 10 6-10 6L2 8z M2 12l10 6 10-6 M2 16l10 6 10-6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',info:'M12 8v.1 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M18 15a5 5 0 0 1 4 5',check:'M4 12l5 5L20 6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const shortDate=s=>s.split('-').reverse().slice(0,2).join('/');
const dayDiff=(a,b)=>Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000);
const vehicles=[{id:'NF-001',name:'Volkswagen Polo',category:'Compacto',owner:'Frota própria',gear:'Automático',seats:5,rate:180,state:'Livre',km:28400},{id:'NF-002',name:'Chevrolet Onix',category:'Compacto',owner:'Frota própria',gear:'Manual',seats:5,rate:160,state:'Em locação',km:32100},{id:'NF-003',name:'Jeep Renegade',category:'SUV',owner:'Parceiro demonstrativo',gear:'Automático',seats:5,rate:280,state:'Livre',km:18700},{id:'NF-004',name:'Toyota Corolla',category:'Executivo',owner:'Parceiro demonstrativo',gear:'Automático',seats:5,rate:320,state:'Em locação',km:22600},{id:'NF-005',name:'Fiat Argo',category:'Compacto',owner:'Frota própria',gear:'Manual',seats:5,rate:150,state:'Manutenção',km:41200},{id:'NF-006',name:'Hyundai Creta',category:'SUV',owner:'Parceiro demonstrativo',gear:'Automático',seats:5,rate:270,state:'Livre',km:15900}];
let bookings=[{id:'RES-101',client:'Marina · exemplo',vehicle:'NF-001',start:'2026-09-27',end:'2026-09-30',time:'09:00',stage:0,paid:false,checks:{},place:'Centro de Gramado'},{id:'RES-102',client:'Rafael · exemplo',vehicle:'NF-002',start:'2026-09-24',end:'2026-09-27',time:'11:30',stage:2,paid:true,checks:{cnh:true,contract:true,deposit:true,out:true},place:'Centro de Canela'},{id:'RES-103',client:'Luiza · exemplo',vehicle:'NF-004',start:'2026-09-25',end:'2026-09-29',time:'14:00',stage:2,paid:true,checks:{cnh:true,contract:true,deposit:true,out:true},place:'Centro de Gramado'}];
const transfers=[{id:'TR-01',from:'Aeroporto POA',to:'Gramado',time:'10:30',client:'Paulo · exemplo',driver:'André · exemplo',status:'Aguardando aceite',value:380},{id:'TR-02',from:'Canela',to:'Vale dos Vinhedos',time:'14:00',client:'Bianca · exemplo',driver:'Carla · exemplo',status:'Confirmado',value:420}];
const stages=['Preparação','Confirmada','Em locação','Devolvida','Encerrada'];
const pages=[['estrategia','layers','Visão & mercado'],['central','grid','Central'],['frota','car','Frota'],['reservas','calendar','Reservas'],['transfer','route','Transfer'],['financeiro','wallet','Financeiro'],['mapa','network','Mapa funcional'],['base','book','Base da vertical'],['evolucao','layers','Evolução']];
let route='central',fleetFilter='Todos',fleetQuery='',bookingFilter='Todas',moduleId='locacao',chapter=0;
const modules={locacao:{name:'Locação',icon:'car',status:'Requisito recuperado',desc:'Do pedido ao encerramento: cada locação reúne veículo, condutor, período, documentação e resultado.',actors:['Cliente / locatário','Gestor da central','Proprietário / locadora parceira'],items:['Disponibilidade por período e prevenção de sobreposição','CNH, contrato, caução e pagamento','Entrega, devolução, multas e ocorrências'],source:'Histórico de 08–09/10/2025 e 15/05/2026. Base funcional, seções 3 e 5.',pending:'Tarifas, regras de caução, cobertura, cancelamento e contrato precisam ser definidos para a operação real.'},frota:{name:'Frota',icon:'car',status:'Planejamento recuperado',desc:'Uma visão dos veículos próprios e de parceiros, da disponibilidade e da condição de cada ativo.',actors:['Gestor','Proprietário / locadora','Motorista'],items:['Ficha do veículo e vínculo com o proprietário','Quilometragem, manutenção e ocorrências','Calendário de reservas e liberação'],source:'Histórico de maio/2026; Diagrama Unificado: Fleet Manager planejado.',pending:'Inventário atual e documentos reais da frota não foram cadastrados.'},transfer:{name:'Transfer',icon:'route',status:'Planejamento recuperado',desc:'Organiza pedidos de deslocamento, disponibilidade de motoristas e acompanhamento de cada serviço.',actors:['Cliente','Motorista parceiro','Central'],items:['Origem, destino, data e horário','Distribuição, aceite e substituição','Conclusão, pagamento e repasse'],source:'Histórico de 23 e 28/05/2026. Base funcional, seção 5.',pending:'Critérios de distribuição, SLA e política de cancelamento ainda precisam de definição.'},clientes:{name:'Clientes',icon:'users',status:'Planejamento recuperado',desc:'O contexto da viagem e o histórico de atendimento acompanham a pessoa, com acesso conforme seu papel.',actors:['Cliente','Central','Nexus OS'],items:['Contato e documentação vinculados à locação','Preferências e histórico de atendimento','Contexto compartilhado conforme governança'],source:'Living Profile e conversas de maio/2026.',pending:'Permissões detalhadas, retenção e integrações de identidade ainda não estão implementadas.'},financeiro:{name:'Financeiro',icon:'wallet',status:'Planejamento recuperado',desc:'Concilia o que foi contratado, recebido e repassado em cada serviço.',actors:['Central','Cliente','Parceiro / indicador'],items:['Cobrança e confirmação de pagamento','Caução registrada separadamente da receita','Apuração e repasse com origem rastreável'],source:'Histórico NepoCenter e Neon Flow. Base funcional, seções 5 e 7.',pending:'Providers, percentuais, base de cálculo e estornos não estão configurados.'},parceiros:{name:'Parceiros',icon:'network',status:'Diretriz recuperada',desc:'Hotéis, comércio e pessoas podem originar pedidos e acompanhar o resultado de suas indicações.',actors:['Hotel / recepção','Comércio / indicador','Motorista / proprietário'],items:['Origem identificada por QR ou indicação','Solicitação ligada ao parceiro','Comissão condicionada a pagamento e conclusão'],source:'Histórico de 09/10/2025 e 23/05/2026.',pending:'Integração de indicações deve preservar a separação de NeoReferral e as regras próprias da vertical.'}};
const $=s=>document.querySelector(s);
const badge=(s,type='grey')=>`<span class="tag ${type}">${esc(s)}</span>`;
const button=(label,action,style='',value='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${value?`data-id="${esc(value)}"`:''}>${label}</button>`;
function heading(eyebrow,title,subtitle,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function total(b){return dayDiff(b.start,b.end)*vehicles.find(v=>v.id===b.vehicle).rate;}
function vehicleState(v){if(v.state==='Manutenção')return 'Manutenção';return bookings.some(b=>b.vehicle===v.id&&b.stage===2)?'Em locação':'Livre';}
function stateTag(s){return badge(s,s==='Livre'||s==='Encerrada'||s==='Recebido'?'ok':s==='Manutenção'||s==='Pendente'?'warn':'blue');}
function demoNote(){return `<div class="note">${icon('info')}<div><strong>Ambiente demonstrativo</strong>Veículos, clientes e valores são exemplos. As simulações duram nesta sessão e reiniciam ao recarregar. A base documental permanece no site.</div></div>`;}
function render(){route=location.hash.slice(1)||'estrategia';if(!pages.some(p=>p[0]===route))route='estrategia';$('#nav').innerHTML=pages.map(p=>`<a class="navitem ${route===p[0]?'active':''}" ${route===p[0]?'aria-current="page"':''} href="#${p[0]}">${icon(p[1])}<span>${p[2]}</span></a>`).join('');const fn={estrategia:strategyPage,central:central,frota:fleet,reservas:reservations,transfer:transferPage,financeiro:finance,mapa:mapPage,base:basePage,evolucao:evolution}[route];$('#content').innerHTML=fn();document.title=`${pages.find(p=>p[0]===route)[2]} · Neon Flow`;}
function central(){const active=bookings.filter(b=>b.stage===2).length,free=vehicles.filter(v=>vehicleState(v)==='Livre').length,pending=bookings.filter(b=>b.stage===0).length;const stats=[['Frota disponível',`${free}<span style="font-size:18px;color:#82949e"> / ${vehicles.length}</span>`,'car','Disponibilidade agora · simulação'],['Locações em curso',String(active).padStart(2,'0'),'route','Veículos em uso · simulação'],['Em preparação',String(pending).padStart(2,'0'),'calendar','Documentos e confirmação'],['Total contratado',money(bookings.filter(b=>b.stage!==-1).reduce((n,b)=>n+total(b),0)),'wallet','Valor das reservas demonstrativas']];return heading('CENTRAL DE MOBILIDADE','Tudo pronto para o próximo trajeto.','Aluguel, frota e contexto em uma única operação.',`<a class="btn" href="#mapa">${icon('network')} Mapa da vertical</a>${button(icon('plus')+' Nova reserva','new','primary')}`)+`<div class="stats">${stats.map(s=>`<div class="stat"><div class="statheader">${s[0]}${icon(s[2])}</div><div class="statvalue">${s[1]}</div><div class="statnote">${s[3]}</div></div>`).join('')}</div><div class="grid"><div><section class="card"><div class="cardhead"><div><h2>Agenda da operação</h2><p>Retiradas e devoluções do cenário</p></div><span class="datepill">27 set · domingo</span></div><div class="timeline">${bookings.filter(b=>b.stage>=0&&b.stage<4&&(b.start==='2026-09-27'||b.end==='2026-09-27')).map(b=>{const v=vehicles.find(v=>v.id===b.vehicle);return `<div class="event"><div class="eventtime">${b.time}</div><div><span class="eventkind">${b.start==='2026-09-27'?'RETIRADA':'DEVOLUÇÃO'}</span><div class="eventtitle">${v.name}</div><div class="eventmeta">${esc(b.client)} · ${esc(b.place)}</div></div>${button('Abrir '+icon('arrow'),'booking','',b.id)}</div>`}).join('')||'<div class="empty">Nenhum atendimento neste dia.</div>'}</div></section><section class="mini-flow"><span class="tag mint">NEXUS OS → NEON FLOW</span><h2 style="margin-top:15px">Cada etapa preserva o contexto.</h2><p>Da intenção de viajar à devolução do veículo.</p><div class="route"><span>Pedido</span><b>→</b><span>Reserva</span><b>→</b><span>Entrega</span><b>→</b><span>Devolução</span><b>→</b><span>Memória</span></div><a class="btn quiet" href="#mapa">Explorar o mapa funcional ${icon('arrow')}</a></section></div><div><section class="card"><div class="cardhead"><div><h2>Disponibilidade da frota</h2><p>${vehicles.length} veículos demonstrativos</p></div><a class="btn quiet" href="#frota">Ver frota ↗</a></div><div class="util"><div class="availability">${vehicles.map(v=>`<span class="${vehicleState(v)==='Em locação'?'busy':vehicleState(v)==='Manutenção'?'maintenance':''}" title="${v.name}: ${vehicleState(v)}"></span>`).join('')}</div><div class="legend"><span>Livre</span><span class="busy">Em locação</span><span class="maintenance">Manutenção</span></div><div class="fleetmini">${vehicles.slice(0,4).map(v=>`<div class="minirow"><div>${v.name}<small>${v.id} · ${v.category}</small></div>${stateTag(vehicleState(v))}</div>`).join('')}</div></div></section>${demoNote()}</div></div><div class="subgrid">${[['reservas','calendar','Do pedido à devolução','Acompanhe e simule o ciclo de locação.'],['base','book','O conhecimento fica aqui','Requisitos, fontes e decisões preservados.'],['evolucao','layers','Próximas evoluções','O que funciona na demo e o que falta conectar.']].map(x=>`<a class="modulelink" href="#${x[0]}"><div class="top">${icon(x[1])}<span>↗</span></div><h3>${x[2]}</h3><p>${x[3]}</p></a>`).join('')}</div>`;}
function fleet(){const list=vehicles.filter(v=>(fleetFilter==='Todos'||vehicleState(v)===fleetFilter)&&`${v.name} ${v.category} ${v.id}`.toLowerCase().includes(fleetQuery.toLowerCase()));return heading('ATIVOS DA VERTICAL','Frota e disponibilidade','Veículos próprios e de parceiros · catálogo demonstrativo.',button(icon('plus')+' Nova reserva','new','primary'))+`<div class="filters"><div class="segments">${['Todos','Livre','Em locação','Manutenção'].map(s=>`<button data-action="fleetfilter" data-id="${s}" class="${s===fleetFilter?'selected':''}" aria-pressed="${s===fleetFilter}">${s}</button>`).join('')}</div><input class="search" id="fleetsearch" aria-label="Buscar veículo" placeholder="Buscar veículo ou categoria" value="${esc(fleetQuery)}"></div><div class="vehicles">${list.map(v=>`<article class="card vehicle"><div class="vehicletop"><span class="vehicleid">${v.id}</span>${stateTag(vehicleState(v))}</div><h2>${v.name}</h2><p>${v.category} · ${v.owner}</p><div class="vehicledetails"><span>${v.gear}</span><span>${v.seats} lugares</span><span>${(v.km/1000).toLocaleString('pt-BR')} mil km</span></div><div class="vehiclebottom"><div class="price">${money(v.rate)}<small>diária de exemplo</small></div>${button('Ver veículo ↗','vehicle','',v.id)}</div></article>`).join('')||'<div class="empty full">Nenhum veículo encontrado.</div>'}</div>${demoNote()}`;}
function bookingTable(list){return `<div class="tablewrap"><table><thead><tr><th>RESERVA / CLIENTE</th><th>VEÍCULO</th><th>PERÍODO</th><th>ETAPA</th><th>VALOR</th><th><span class="muted">DETALHES</span></th></tr></thead><tbody>${list.map(b=>`<tr><td><strong>${esc(b.client)}</strong><small>${b.id}</small></td><td>${vehicles.find(v=>v.id===b.vehicle).name}</td><td>${shortDate(b.start)} → ${shortDate(b.end)}<small>${dayDiff(b.start,b.end)} diárias</small></td><td>${stateTag(b.stage===-1?'Cancelada':stages[b.stage])}</td><td>${money(total(b))}<small>${b.paid?'Recebido (simulado)':'Pagamento pendente'}</small></td><td>${button('Abrir','booking','',b.id)}</td></tr>`).join('')}</tbody></table></div>`;}
function reservations(){const list=bookings.filter(b=>bookingFilter==='Todas'||(bookingFilter==='Ativas'?b.stage>=0&&b.stage<4:b.stage===4||b.stage===-1));return heading('CICLO DE LOCAÇÃO','Reservas e locações','Período, cliente e documentação acompanham cada reserva.',button(icon('plus')+' Nova reserva','new','primary'))+`<div class="filters"><div class="segments">${['Todas','Ativas','Finalizadas'].map(s=>`<button class="${s===bookingFilter?'selected':''}" data-action="bookfilter" data-id="${s}">${s}</button>`).join('')}</div><span class="muted" style="font-size:14px">${list.length} reservas no cenário</span></div><section class="card">${list.length?bookingTable(list):'<div class="empty">Nenhuma reserva nesta categoria.</div>'}</section><div class="flowsteps">${[['01','Preparação','Condutor, contrato e caução'],['02','Confirmação','Pagamento e período reservado'],['03','Locação','Entrega e uso do veículo'],['04','Encerramento','Devolução, conferência e liberação']].map(x=>`<div class="flowstep"><b>${x[0]}</b><strong>${x[1]}</strong><p class="subtitle">${x[2]}</p></div>`).join('')}</div>${demoNote()}`;}
function transferPage(){return heading('MOBILIDADE & TURISMO','Transfer e motoristas','Uma segunda jornada da mesma vertical. Serviços demonstrativos.')+`<div class="notice">Ações abaixo simulam aceite e conclusão. Não enviam pedidos ou mensagens a motoristas.</div><div class="vehicles">${transfers.map(t=>`<section class="card detail">${stateTag(t.status)}<div class="transferroute"><div><strong>${t.from}</strong><small>Origem</small></div><span>→</span><div><strong>${t.to}</strong><small>Destino</small></div></div><p>27 set · ${t.time}</p><div class="minirow"><div>Cliente<small>${t.client}</small></div><div>Motorista<small>${t.driver}</small></div></div><div class="minirow"><strong>${money(t.value)}</strong><span class="muted">Valor de exemplo</span></div>${t.status==='Concluído'?badge('Serviço encerrado','ok'):button(t.status==='Aguardando aceite'?'Simular aceite':'Simular conclusão','transfer','primary',t.id)}</section>`).join('')}<section class="card detail">${badge('A definir','warn')}<h2>Rede de parceiros</h2><p>Hotéis, recepções, comércio e motoristas podem originar solicitações de aluguel e transfer.</p><h3>Antes da operação real</h3><ul><li>Cadastro e aprovação dos parceiros</li><li>Critérios de distribuição e aceite</li><li>Origem e regras de comissão</li></ul><a class="btn" href="#mapa">Ver conexões ${icon('network')}</a></section></div>${demoNote()}`;}
function finance(){const valid=bookings.filter(b=>b.stage!==-1),received=valid.filter(b=>b.paid).reduce((n,b)=>n+total(b),0),pending=valid.filter(b=>!b.paid).reduce((n,b)=>n+total(b),0);return heading('CONCILIAÇÃO DO CENÁRIO','Financeiro','Valores demonstrativos vinculados às reservas desta sessão.')+`<div class="stats"><div class="stat"><div class="statheader">Contratado ${icon('wallet')}</div><div class="statvalue">${money(received+pending)}</div><p class="statnote">Reservas não canceladas</p></div><div class="stat"><div class="statheader">Recebido (simulado)</div><div class="statvalue">${money(received)}</div><p class="statnote">Sem transações financeiras reais</p></div><div class="stat"><div class="statheader">Pendente</div><div class="statvalue">${money(pending)}</div><p class="statnote">Confirmação pela central</p></div><div class="stat"><div class="statheader">Repasses</div><div class="statvalue" style="font-size:23px">A definir</div><p class="statnote">Percentuais ainda não configurados</p></div></div><section class="card"><div class="cardhead"><h2>Pagamentos por reserva</h2></div><div class="tablewrap"><table><thead><tr><th>RESERVA</th><th>CLIENTE</th><th>VALOR</th><th>ESTADO</th><th>AÇÃO</th></tr></thead><tbody>${valid.map(b=>`<tr><td>${b.id}</td><td>${esc(b.client)}</td><td>${money(total(b))}</td><td>${stateTag(b.paid?'Recebido':'Pendente')}</td><td>${b.paid?'—':button('Simular recebimento','pay','',b.id)}</td></tr>`).join('')}</tbody></table></div></section><div class="note">${icon('info')}<div><strong>Caução e comissão têm regras próprias.</strong>A caução não é contabilizada como receita nesta demonstração. Percentuais históricos não foram transformados em regras vigentes. Cancelamentos pagos exigirão um fluxo de reembolso na operação real.</div></div>`;}
function mapPage(){const m=modules[moduleId];return heading('ARQUITETURA DA VERTICAL','Um mapa que conecta a operação.','Selecione um módulo para explorar responsabilidades, fontes e pendências.')+`<div class="maplayout"><div class="mapcanvas"><div class="core"><strong>NEXUS OS</strong><small>Identidade · contexto · eventos · governança</small></div><div class="connector"></div><div class="verticalnode"><strong>Neon Flow</strong><small>Aluguel · frota · mobilidade</small></div><div class="connector"></div><div class="nodes">${Object.entries(modules).map(([id,m])=>`<button class="node ${moduleId===id?'selected':''}" data-action="module" data-id="${id}" aria-pressed="${moduleId===id}">${icon(m.icon)}${m.name}</button>`).join('')}</div><p class="mapcaption">Ator · Ativo · Evento · Contexto · Fluxo<br>Base conceitual compartilhada entre verticais</p></div><section class="card detail">${badge(m.status,'blue')}<h2>${m.name}</h2><p>${m.desc}</p><h3>Quem participa</h3><div class="actions">${m.actors.map(a=>badge(a)).join('')}</div><h3>Responsabilidades</h3><ul>${m.items.map(x=>`<li>${x}</li>`).join('')}</ul><div class="source"><strong>Origem do requisito</strong><p style="font-size:13px;margin-top:5px">${m.source}</p></div><h3>O que falta decidir</h3><p style="font-size:14px">${m.pending}</p><a class="btn quiet space" href="#base">Abrir base completa ↗</a></section></div><div class="subgrid"><div class="modulelink"><div class="eyebrow">ATOR + ATIVO</div><h3>Pessoa e veículo</h3><p>Cliente, condutor, gestor e parceiro associados ao carro ou à van.</p></div><div class="modulelink"><div class="eyebrow">EVENTO + CONTEXTO</div><h3>O que aconteceu e por quê</h3><p>Reserva, entrega e devolução ligadas ao período e à necessidade da viagem.</p></div><div class="modulelink"><div class="eyebrow">FLUXO</div><h3>Uma operação rastreável</h3><p>As etapas preservam histórico, responsabilidade e resultado.</p></div></div>`;}
function inline(s){return esc(s).replace(/\[([^\]]+)\]\((https:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdown(text){const lines=text.split('\n');let html='',table=false,list=false;for(const l of lines){if(l.startsWith('|')){if(list){html+='</ul>';list=false}if(!table){html+='<div class="mdtable"><table>';table=true}if(/^\|[\s:|-]+\|$/.test(l))continue;html+='<tr>'+l.split('|').slice(1,-1).map(c=>`<td>${inline(c.trim())}</td>`).join('')+'</tr>';continue;}if(table){html+='</table></div>';table=false}if(/^[-*] /.test(l)){if(!list){html+='<ul>';list=true}html+='<li>'+inline(l.slice(2))+'</li>';continue}if(list){html+='</ul>';list=false}if(l.startsWith('### '))html+='<h3>'+inline(l.slice(4))+'</h3>';else if(l.trim())html+='<p>'+inline(l)+'</p>';}return html+(table?'</table></div>':'')+(list?'</ul>':'');}
function basePage(){return heading('CONHECIMENTO PRESERVADO','Base da vertical','Base v1.1 preservada; capítulos 13–16 complementam e retificam a pesquisa em 29 set 2026.',`<a class="btn" href="NEON_FLOW_BASE_FUNCIONAL_v1_1.md" download>Baixar base v1.1 ↓</a>`)+`<div class="knowledge"><nav class="chapterlist" aria-label="Capítulos da base">${CHAPTERS.map((c,i)=>`<button data-action="chapter" data-id="${i}" class="${chapter===i?'selected':''}" aria-pressed="${chapter===i}">${esc(c.title)}</button>`).join('')}</nav><article class="card doc"><h2>${esc(CHAPTERS[chapter].title)}</h2>${markdown(CHAPTERS[chapter].body)}</article></div>`;}
function evolution(){return heading('DESENVOLVIMENTO DA VERTICAL','Uma base viva, com próximos passos claros.','Demonstração disponível agora. Integrações reais dependem de especificação e validação.')+`<div class="roadmap"><section class="roadcol"><h2>01 / Disponível nesta versão</h2>${[['Central e frota','Navegação, filtros e fichas de veículos demonstrativos.'],['Ciclo da locação','Criar reserva, impedir sobreposição e simular confirmação, entrega e devolução.'],['Mapa e documentação','Módulos selecionáveis, fontes, decisões e base para download.']].map(x=>`<article class="roaditem">${badge('Demonstração funcional','ok')}<h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</section><section class="roadcol"><h2>02 / Definir com a operação</h2>${[['Frota e tarifas','Veículos realmente ofertados, diárias, limites de uso e manutenção.'],['Política de locação','Condutor, caução, cobertura, cancelamento, atrasos e ocorrências.'],['Parceiros e repasses','Critérios de distribuição, SLA, comissão e base de cálculo.']].map(x=>`<article class="roaditem">${badge('Decisão pendente','warn')}<h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</section><section class="roadcol"><h2>03 / Conectar e validar</h2>${[['Dados e acesso','Banco persistente, autenticação e permissões por perfil.'],['Contratos e pagamentos','Assinatura, cobranças, conciliação e reembolso com providers reais.'],['Nexus OS','Identidade, contexto e eventos compartilhados com evidências de execução.']].map(x=>`<article class="roaditem">${badge('Planejado','blue')}<h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</section></div><section class="card detail space"><div class="eyebrow">REGISTRO DE EVOLUÇÃO</div><h2>29 set 2026 · Visão e mercado</h2><p>Pesquisa aprofundada incorporada: intenção do fundador, entrada proposta no mercado, rede de parceiros, papéis Nexus/Shell e fontes. Retificação da autoria das propostas de 27/08/2026. <a href="#estrategia">Abrir revisão estratégica</a></p><h2>27 set 2026 · Primeira base navegável</h2><p>Nome Neon Flow corrigido conforme o fundador. Base funcional v1.1 incorporada. Simulações de locação e transfer preservam a distinção entre interface demonstrativa e operação real.</p><div class="source"><strong>Fonte ainda a recuperar</strong><p>NEON_FLOW_cartao_executivo.pdf: citado no catálogo histórico, mas o PDF original ainda não foi localizado. Sua existência é uma referência documental; seu conteúdo não foi presumido.</p></div></section>`;}
function showModal(html){$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function modalHead(title,sub){return `<div class="modalhead"><div><h2>${title}</h2><p>${sub}</p></div><button class="close" data-action="close" aria-label="Fechar">×</button></div>`;}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function newBooking(id){showModal(modalHead('Nova reserva','Simulação · não contrata nem cobra um serviço')+`<form id="bookingform"><div class="formgrid"><div class="field full"><label for="client">Nome de exemplo</label><input id="client" name="client" maxlength="60" placeholder="Ex.: Cliente de demonstração" required><p class="formhint">Use dados fictícios neste protótipo.</p></div><div class="field full"><label for="vehicle">Veículo</label><select id="vehicle" name="vehicle">${vehicles.filter(v=>v.state!=='Manutenção').map(v=>`<option value="${v.id}" ${id===v.id?'selected':''}>${v.name} · ${money(v.rate)}/dia</option>`).join('')}</select></div><div class="field"><label for="start">Retirada</label><input id="start" name="start" type="date" value="2026-10-01" required></div><div class="field"><label for="end">Devolução</label><input id="end" name="end" type="date" value="2026-10-04" required></div><div class="field full"><label for="place">Local de retirada</label><select id="place" name="place"><option>Centro de Gramado</option><option>Centro de Canela</option><option>Aeroporto POA</option></select></div></div><div class="summary" id="quote"></div><p class="formhint">O período fica bloqueado nesta simulação ao criar a reserva. Caução, taxas e extras não estão incluídos.</p><div class="error" id="formerror" role="alert"></div><div class="modalfooter">${button('Cancelar','close')}<button class="btn primary" type="submit">Criar reserva demonstrativa</button></div></form>`);updateQuote();}
function updateQuote(){if(!$('#bookingform'))return;const v=vehicles.find(v=>v.id===$('#vehicle').value);const n=dayDiff($('#start').value,$('#end').value);$('#quote').innerHTML=Number.isFinite(n)&&n>0?`<span>${n} diárias × ${money(v.rate)}<br><small>Valor demonstrativo</small></span><b>${money(n*v.rate)}</b>`:'Selecione um período válido.';}
function createBooking(data){const v=vehicles.find(v=>v.id===data.vehicle);if(!v||v.state==='Manutenção')throw Error('Veículo indisponível.');if(!data.client.trim())throw Error('Informe um nome de exemplo.');if(!/^\d{4}-\d{2}-\d{2}$/.test(data.start)||!/^\d{4}-\d{2}-\d{2}$/.test(data.end)||!(dayDiff(data.start,data.end)>0))throw Error('A devolução deve ser posterior à retirada.');if(bookings.some(b=>b.vehicle===v.id&&b.stage>=0&&b.stage<4&&data.start<b.end&&data.end>b.start))throw Error('Este veículo já tem uma reserva nesse período. Escolha outras datas ou outro veículo.');const b={id:'RES-'+(104+bookings.length-3),client:data.client.trim().slice(0,60),vehicle:v.id,start:data.start,end:data.end,place:data.place,time:'09:00',stage:0,paid:false,checks:{}};bookings.push(b);return b;}
function vehicleModal(id){const v=vehicles.find(v=>v.id===id),bs=bookings.filter(b=>b.vehicle===id&&b.stage>=0&&b.stage<4);showModal(modalHead(v.name,`${v.id} · Veículo demonstrativo`)+stateTag(vehicleState(v))+`<div class="minirow"><span>Categoria</span><strong>${v.category}</strong></div><div class="minirow"><span>Vínculo</span><strong>${v.owner}</strong></div><div class="minirow"><span>Câmbio / lugares</span><strong>${v.gear} / ${v.seats}</strong></div><div class="minirow"><span>Quilometragem de exemplo</span><strong>${v.km.toLocaleString('pt-BR')} km</strong></div><div class="minirow"><span>Diária de exemplo</span><strong>${money(v.rate)}</strong></div><h3 class="space">Períodos reservados</h3>${bs.length?bs.map(b=>`<div class="minirow"><span>${shortDate(b.start)} → ${shortDate(b.end)}</span>${button(b.id+' ↗','booking','quiet',b.id)}</div>`).join(''):'<p class="subtitle">Nenhuma reserva ativa para este veículo.</p>'}<div class="note"><div><strong>Documentos e manutenção</strong>CRLV, seguro e registros reais ainda não foram cadastrados.</div></div><div class="modalfooter">${button('Fechar','close')}${v.state==='Manutenção'?badge('Bloqueado para manutenção','warn'):button('Reservar período','new','primary',v.id)}</div>`);}
const checklist={cnh:'Condutor e CNH conferidos',contract:'Contrato assinado (simulação)',deposit:'Caução conferida (simulação)',out:'Checklist de entrega concluído',back:'Checklist de devolução concluído',issues:'Ocorrências e pendências conferidas'};
function bookingModal(id){const b=bookings.find(b=>b.id===id),v=vehicles.find(v=>v.id===b.vehicle);const keys=b.stage===0?['cnh','contract','deposit']:b.stage===1?['out']:b.stage===2?['back']:b.stage===3?['issues']:[];showModal(modalHead(b.id+' · '+v.name,esc(b.client))+`<div class="stagebar">${stages.map((s,i)=>`<span class="${i===b.stage?'current':''}">${s}</span>`).join('')}</div><div class="minirow"><span>Período</span><strong>${shortDate(b.start)} → ${shortDate(b.end)}</strong></div><div class="minirow"><span>Local</span><strong>${esc(b.place)}</strong></div><div class="minirow"><span>Contratado</span><strong>${money(total(b))}</strong></div><div class="minirow"><span>Pagamento</span>${b.paid?badge('Recebido · simulado','ok'):button('Simular recebimento','pay','',b.id)}</div>${keys.length?`<h3 class="space">Conferência da etapa</h3><div class="checklist">${keys.map(k=>`<label><input type="checkbox" data-book="${b.id}" data-check="${k}" ${b.checks[k]?'checked':''}>${checklist[k]}</label>`).join('')}</div>`:''}<div class="error" id="stageerror" role="alert"></div>${b.stage===-1?'<p class="subtitle">Reserva cancelada. O período está liberado. Nenhuma cobrança real foi feita.</p>':''}<div class="modalfooter">${b.stage>=0&&b.stage<2?button('Cancelar reserva','cancelbooking','',b.id):button('Fechar','close')}${b.stage>=0&&b.stage<4?button(['Confirmar reserva','Registrar entrega','Registrar devolução','Encerrar locação'][b.stage],'advance','primary',b.id):badge(b.stage===4?'Locação encerrada':'Cancelada','grey')}</div><p class="formhint space">Checklists apenas demonstrativos. Nenhum documento foi verificado ou assinado de verdade.</p>`);}
function advance(id){const b=bookings.find(b=>b.id===id);const keys=b.stage===0?['cnh','contract','deposit']:b.stage===1?['out']:b.stage===2?['back']:['issues'];if(keys.some(k=>!b.checks[k])||(b.stage===0&&!b.paid)){ $('#stageerror').textContent='Conclua a conferência da etapa'+(b.stage===0?' e simule o recebimento para confirmar.':'.');return;}b.stage++;render();bookingModal(id);toast('Etapa atualizada na demonstração.');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){case 'new':newBooking(id);break;case 'close':closeModal();break;case 'vehicle':vehicleModal(id);break;case 'booking':bookingModal(id);break;case 'module':moduleId=id;render();break;case 'chapter':chapter=Number(id);render();break;case 'fleetfilter':fleetFilter=id;render();break;case 'bookfilter':bookingFilter=id;render();break;case 'advance':advance(id);break;case 'pay':{const b=bookings.find(b=>b.id===id);b.paid=true;render();if($('#modal').open)bookingModal(id);toast('Recebimento simulado. Nenhuma cobrança real.');break;}case 'cancelbooking':showModal(modalHead('Cancelar reserva?','O período será liberado nesta simulação.')+`<p>Esta ação afeta apenas ${id}. Nenhum pagamento ou reembolso real será feito.</p><div class="modalfooter">${button('Voltar','booking','',id)}${button('Confirmar cancelamento','confirmcancel','primary',id)}</div>`);break;case 'confirmcancel':bookings.find(b=>b.id===id).stage=-1;closeModal();render();toast('Reserva cancelada no cenário.');break;case 'transfer':{const t=transfers.find(t=>t.id===id);t.status=t.status==='Aguardando aceite'?'Confirmado':'Concluído';render();toast('Transfer atualizado na demonstração.');break;}}});
document.addEventListener('input',e=>{if(e.target.id==='fleetsearch'){const position=e.target.selectionStart;fleetQuery=e.target.value;render();$('#fleetsearch').focus();$('#fleetsearch').setSelectionRange(position,position);}if(['start','end','vehicle'].includes(e.target.id))updateQuote();});
document.addEventListener('change',e=>{if(e.target.dataset.check){const b=bookings.find(b=>b.id===e.target.dataset.book);b.checks[e.target.dataset.check]=e.target.checked;}if(e.target.id==='vehicle')updateQuote();});
document.addEventListener('submit',e=>{if(e.target.id!=='bookingform')return;e.preventDefault();try{const b=createBooking(Object.fromEntries(new FormData(e.target)));closeModal();location.hash='reservas';render();bookingModal(b.id);toast('Reserva demonstrativa criada.');}catch(err){$('#formerror').textContent=err.message;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_demo_reservations',title:'Consultar reservas demonstrativas',description:'Retorna reservas de exemplo desta sessão; não são reservas reais.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('Nenhum parâmetro é aceito.');return {demo:true,bookings:bookings.map(b=>({id:b.id,vehicle:b.vehicle,start:b.start,end:b.end,stage:b.stage===-1?'Cancelada':stages[b.stage]}))};}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'navigate_neon_flow',title:'Abrir área do Neon Flow',description:'Navega para uma área visível da demonstração sem criar registros.',inputSchema:{type:'object',properties:{area:{type:'string',enum:pages.map(p=>p[0])}},required:['area'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='area')||!pages.some(p=>p[0]===input.area))throw Error('Área inválida.');location.hash=input.area;render();return {area:input.area,demo:true};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
